// System Call: Standard I/O (Trap to Kernel Mode)
// Registers loaded with args before interrupt instruction
const char buf[] = "Request";
ssize_t bytes_written = write(
    1,          // STDOUT_FILENO
    buf,
    sizeof(buf) - 1
);
// Kernel returns control flow (and return value)
// back to User Mode upon completion.

// ECF: Synchronous Exception (Trap)
// Triggered by CPU violating invariant
void cause_fault() {
    // 1. Division by Zero (SIGFPE)
    int x = 1 / 0; 

    // 2. Illegal memory access (SIGSEGV)
    char* p = (char*)0xDEADBEEF;
    *p = 'X'; 
}

// ECF: Asynchronous Signal Handling
void signal_handler(int sig) {
    if (sig == 2) { // SIGINT
        // Kernel interrupted user process
        // to deliver signal
    }
}

struct sigaction sa;
sa.sa_handler = signal_handler;
sigaction(SIGINT, &sa, NULL);
// Process resumes until SIGINT occurs.
